

var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"LuckyBellsAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.xgl.vmd!=undefined){
			
			if(gameController.pjo!=parseInt(tmpMess[1])){
				
			gameController.pjo=parseInt(tmpMess[1]);	
			gameController.xgl.vmd.opy("creditd", "#gkw", [gameController.ifh(tmpMess[1]), true]);	
				
			}
			
			
			
			
			
			}	
			
		}
		
